def _f_star(ctx):
    """Kelly's f from the strategy's OWN last N closed trades on this symbol."""
    n = int(ctx.p.ledger_n)
    tr = ctx.closed[-n:]
    if len(tr) < int(ctx.p.min_ledger):
        return None
    wins = []
    loss = []
    for t in tr:
        d = -1.0 if t["side"] == "short" else 1.0
        pl = (t["exit"] - t["entry"]) * t["shares"] * d - float(t.get("fees") or 0.0)
        if pl > 0:
            wins.append(pl)
        else:
            loss.append(-pl)
    if not wins or not loss:
        return None
    W = len(wins) / float(len(tr))
    A = sum(wins) / len(wins)
    B = sum(loss) / len(loss)
    if B <= 0 or A <= 0:
        return None
    R = A / B
    return W - (1.0 - W) / R


def family_init(ctx):
    ctx.dh = ctx.indicator("donchian", period=int(ctx.p.dc_in))
    ctx.dl = ctx.indicator("donchian", period=int(ctx.p.dc_out))
    ctx._veto = 0


def signal(ctx, i):
    if i < 2:
        return 0
    u = ctx.dh.upper[i - 1]
    pu = ctx.dh.upper[i - 2]
    if u is None or pu is None:
        return 0
    if not (ctx.c[i] > u and ctx.c[i - 1] <= pu):
        return 0                        # the fixed entry harness, held constant
    a = ctx.a[i]
    if a is None or a <= 0:
        return 0

    f = _f_star(ctx)
    if f is None:
        rf = float(ctx.p.warm_risk)     # before the ledger is deep enough
    elif f > 0:
        rf = min(max(float(ctx.p.kelly_c) * f, 0.0), float(ctx.p.risk_cap))
        ctx._veto = 0
    else:
        # The ledger says there is no edge. Skip -- but a rule that only ever
        # recomputes on a CLOSED trade can never leave this state on its own,
        # so after probe_n consecutive vetoes one signal is taken at the floor
        # size purely to refresh the ledger. probe_n is swept, and one arm of
        # the sweep is large enough to be the literal absorbing rule.
        ctx._veto += 1
        if ctx._veto < int(ctx.p.probe_n):
            return 0
        ctx._veto = 0
        rf = float(ctx.p.warm_risk)

    per_share = float(ctx.p.st_atr) * a
    if per_share <= 0:
        return 0
    eq = float(ctx.p.equity0) + ctx.realized
    if eq <= 0:
        return 0
    n = int(rf * eq / per_share)
    if n < 1:
        return 0
    ctx.p.shares = min(n, int(ctx.p.max_shares))
    return 1


def exit_signal(ctx, i):
    if not ctx.positions or i < 1:
        return False
    lo = ctx.dl.lower[i - 1]
    if lo is None:
        return False
    return ctx.c[i] < lo
